import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex } from 'antd';

import PlusIcon from 'assets/images/icons/plus.svg?react';
import { ChannelCard, useChannelsListQuery } from 'entities/Channel';
import { ChannelsFilters, EFilters, getUrlParamsForApi, useFilters } from 'features/Filters';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { ButtonStyleLink, NoResults, OverlayLoader } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

interface IChannelsListProps extends HTMLAttributes<HTMLDivElement> {}

export const ChannelsList: FC<IChannelsListProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const [searchParams] = useSearchParams();
	const { data, isFetching, isLoading } = useChannelsListQuery(getUrlParamsForApi(searchParams));
	const { getFiltersCount } = useFilters();
	const hasFilters = getFiltersCount([EFilters.STATUS, EFilters.NAME]) > 0;

	return (
		<Flex {...props} vertical gap={12}>
			{isFetching && <OverlayLoader />}

			<Flex vertical gap={8}>
				<ChannelsFilters />
				{!isLoading && !data?.results.length && (
					<NoResults
						text={t('Нет каналов')}
						subtext={
							hasFilters
								? t('Нет результатов для этого поискового запроса')
								: t('Вы пока не добавили еще ни одного канала или группы')
						}
					/>
				)}
				<ButtonStyleLink
					type="primary"
					size="large"
					to={`/${EMainRoutes.CHANNELS}/${EMainRoutes.CREATE}`}
					icon={<PlusIcon />}
					onClick={() => sendYmEvent('click_add_channel', { page_screen: EYmPageScreen.YOUR_CHANNELS_SCREEN })}
					iconPosition="end">
					{t('Добавить канал')}
				</ButtonStyleLink>
			</Flex>

			<Flex vertical gap={12}>
				{data?.results.map((channel) => <ChannelCard key={channel.uuid} channel={channel} />)}
			</Flex>
		</Flex>
	);
};
