import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Checkbox, Flex, Input } from 'antd';

import { ChannelStatusEnum } from 'entities/Channel';
import { EFilters, useFilters } from 'features/Filters';
import { InputClearIcon } from 'shared/ui';

interface IChannelsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ChannelsFilters: FC<IChannelsFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();

	const { getFilterValue, getALLFilterValues, onFilterChange } = useFilters(true);

	const [search, setSearch] = useState(getFilterValue(EFilters.NAME) || '');

	const notActiveStatuses = [
		ChannelStatusEnum.Rejected,
		/*ChannelStatusEnum.NotAdmin,
		ChannelStatusEnum.Restricted,
		ChannelStatusEnum.Banned,
		ChannelStatusEnum.NotEnoughSubscribers,*/
	];
	const selectedStatuses = getALLFilterValues(EFilters.STATUS);

	return (
		<Flex {...props} vertical gap={8}>
			<Input.Search
				placeholder={t('Поиск')}
				onSearch={(value) => onFilterChange(EFilters.NAME, value)}
				onChange={(e) => setSearch(e.target.value)}
				value={search.trimStart()}
				allowClear={{ clearIcon: <InputClearIcon /> }}
				size="large"
			/>

			<Checkbox
				onChange={(e) => {
					onFilterChange(EFilters.STATUS, e.target.checked ? notActiveStatuses : null);
				}}
				checked={notActiveStatuses.every((status) => selectedStatuses.includes(status))}>
				{t('Неактивные')}
			</Checkbox>
		</Flex>
	);
};
