import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Card, CardProps, Flex, Tag, Typography } from 'antd';

import {
	ChannelAvatar,
	ChannelRead,
	ChannelStatChange,
	ChannelStatusAlert,
	ChannelStatusEnum,
	ChannelSubscribers,
} from 'entities/Channel';
import { CATEGORIES } from 'shared/consts';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';
import { formatNumber, getNoun } from 'shared/utils';

interface IChannelCardProps extends CardProps {
	channel: ChannelRead;
}

export const ChannelCard: FC<IChannelCardProps> = ({ channel, ...props }) => {
	const { t } = useTranslation();
	const isBlocked = channel.status === ChannelStatusEnum.Rejected;

	const currentClicks = channel.metrics?.current_period?.clicks_count;
	const currentClicksNumber = Number.isNaN(currentClicks) ? 0 : Number(currentClicks);
	const prevClicks = channel.metrics?.prev_period?.clicks_count;
	const prevClicksNumber = Number.isNaN(prevClicks) ? 0 : Number(prevClicks);

	const currentEarned = channel.metrics?.current_period?.earned;
	const currentEarnedNumber = Number.isNaN(currentEarned) ? 0 : Number(currentEarned);
	const prevEarned = channel.metrics?.prev_period?.earned;
	const prevEarnedNumber = Number.isNaN(prevEarned) ? 0 : Number(prevEarned);

	const currentClicksArrow =
		currentClicksNumber > prevClicksNumber ? 'up' : currentClicksNumber < prevClicksNumber ? 'down' : 'equal';
	const currentEarnedArrow =
		currentEarnedNumber > prevEarnedNumber ? 'up' : currentEarnedNumber < prevEarnedNumber ? 'down' : 'equal';

	return (
		<Card {...props} variant="borderless" styles={{ body: { padding: '12px 8px' } }}>
			<Flex vertical gap={12}>
				<Flex gap={8}>
					<ChannelAvatar name={channel.name} logo={channel.logo_url} status={channel.status} size={44} />

					<Flex vertical gap={4}>
						<Flex gap={8}>
							<Typography.Text strong type={isBlocked ? 'secondary' : undefined}>
								{channel.name}
							</Typography.Text>

							<ChannelSubscribers count={channel.subscribers_count} />
						</Flex>

						<Flex wrap gap={4}>
							{channel.categories?.map((category) => (
								<Tag key={category} color="blue" style={{ margin: 0, filter: isBlocked ? 'grayscale(100%)' : 'none' }}>
									{CATEGORIES[category] || category}
								</Tag>
							))}
						</Flex>
					</Flex>
				</Flex>

				<Flex vertical gap={4}>
					<Typography.Text type="secondary">{t('За последние 7 дней:')}</Typography.Text>
					<Flex gap={12}>
						<ChannelStatChange arrow={currentClicksArrow}>
							{formatNumber(currentClicksNumber)} {getNoun(currentClicksNumber, [t('клик'), t('клика'), t('кликов')])}
						</ChannelStatChange>
						<ChannelStatChange arrow={currentEarnedArrow}>
							{formatNumber(currentEarnedNumber)} {t('руб')}
						</ChannelStatChange>
					</Flex>
				</Flex>

				<ChannelStatusAlert status={channel?.status} />

				{!isBlocked && (
					<ButtonStyleLink to={`/${EMainRoutes.CHANNEL}/${channel.uuid}`} size="large">
						{t('Подробнее')}
					</ButtonStyleLink>
				)}

				{isBlocked && (
					<Button href="mailto:support@telerev.com" variant="outlined" color="primary" size="large">
						{t('Вернуть канал')}
					</Button>
				)}
			</Flex>
		</Card>
	);
};
